INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22401, 'ចំណុច \((1, 5), (3, 11), (5, 17)\) ស្ថិតនៅលើបន្ទាត់តែមួយ ។ តើមេគុណប្រាប់ទិសនៃបន្ទាត់នោះស្មើប៉ុន្មាន?', NULL, '["\\(5\\)", "\\(3\\)", "\\(4\\)", "\\(2\\)"]', 1, NULL, 1, 'mcq', 'ផលធៀប \(\frac{11-5}{3-1} = \frac{6}{2} = 3\) ដូច្នេះមេគុណប្រាប់ទិសស្មើ \(3\) ។', 'ទំនាក់ទំនងលីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22402, 'ចំពោះចំណុចទិន្នន័យ \((x_i, y_i)\) និងបន្ទាត់ \(y = ax + b\) តើគម្លាតឈរ \(d_i\) កំណត់ដោយរូបមន្តណា?', NULL, '["\\(d_i = y_i + (ax_i + b)\\)", "\\(d_i = x_i - (ay_i + b)\\)", "\\(d_i = y_i - (ax_i + b)\\)", "\\(d_i = (ax_i + b)y_i\\)"]', 2, NULL, 1, 'mcq', 'គម្លាតឈរពីចំណុចទិន្នន័យទៅបន្ទាត់គឺ \(d_i = y_i - (ax_i + b)\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22403, 'តម្លៃមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) ប្រែប្រួលក្នុងចន្លោះណា?', NULL, '["\\(-1 \\le r \\le 1\\)", "\\(r \\ge 0\\)", "\\(-1 < r < 1\\)", "\\(0 \\le r \\le 1\\)"]', 0, NULL, 1, 'mcq', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) តែងតែស្ថិតក្នុងចន្លោះ \(-1 \le r \le 1\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22404, 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែររវាងម៉ោងសិក្សា \(x\) និងពិន្ទុ \(y\) គឺ \(y = 4x + 15\) ។ ប៉ាន់ស្មានពិន្ទុពេល \(x = 5\) ។', NULL, '["\\(40\\)", "\\(20\\)", "\\(30\\)", "\\(35\\)"]', 3, NULL, 1, 'mcq', 'ជំនួស \(x = 5\) បាន \(y = 4(5) + 15 = 35\) ។', 'ការប៉ាន់ស្មានដោយបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22405, 'គេមានតារាងទិន្នន័យ \((0, 4), (2, 10), (4, 16), (6, 22)\) ។ រកសមីការបន្ទាត់ដែលកាត់តាមចំណុចទាំងនេះ ។', NULL, '["\\(y = 6x + 4\\)", "\\(y = 4x + 3\\)", "\\(y = 2x + 4\\)", "\\(y = 3x + 4\\)"]', 3, NULL, 1, 'mcq', 'មេគុណប្រាប់ទិស \(a = \frac{10-4}{2-0} = 3\) និងអរដោនេដើម \(b = 4\) ដូច្នេះ \(y = 3x + 4\) ។', 'ទំនាក់ទំនងលីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22406, 'បន្ទាត់ \(y = ax + b\) ជាបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ លុះត្រាតែផលបូកណាមួយមានតម្លៃតូចបំផុត?', NULL, '["\\(\\sum_{i=1}^{n} d_i\\)", "\\(\\sum_{i=1}^{n} d_i^2\\)", "\\(\\sum_{i=1}^{n} x_i y_i\\)", "\\(\\sum_{i=1}^{n} x_i^2\\)"]', 1, NULL, 1, 'mcq', 'លក្ខខណ្ឌតម្រែតម្រង់លីនេអ៊ែរគឺផលបូកការេប្រវែង \(\sum_{i=1}^{n} d_i^2\) មានតម្លៃតូចបំផុត ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22407, 'កាលណាមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r = 1\) តើចំណុចទិន្នន័យមានលក្ខណៈដូចម្តេច?', NULL, '["ស្ថិតនៅលើបន្ទាត់តែមួយដែលមានមេគុណប្រាប់ទិសវិជ្ជមាន", "នៅរាយប៉ាយឆ្ងាយពីបន្ទាត់និងគ្មានទំនាក់ទំនងលីនេអ៊ែរ", "ស្ថិតនៅលើបន្ទាត់តែមួយដែលមានមេគុណប្រាប់ទិសអវិជ្ជមាន", "មានទំនាក់ទំនងលីនេអ៊ែរខ្សោយ"]', 0, NULL, 1, 'mcq', '\(r = 1\) បញ្ជាក់ថាចំណុចទាំងអស់ស្ថិតនៅលើបន្ទាត់កើនតែមួយ (ទំនាក់ទំនងលីនេអ៊ែរល្អឥតខ្ចោះ) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22408, 'បន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ \(y = ax + b\) តែងតែកាត់តាមចំណុចណាជានិច្ច?', NULL, '["\\((a, b)\\)", "\\((1, 1)\\)", "\\((\\bar{x}, \\bar{y})\\)", "\\((0, 0)\\)"]', 2, NULL, 1, 'mcq', 'ដោយ \(b = \bar{y} - a\bar{x}\) នាំឱ្យ \(\bar{y} = a\bar{x} + b\) ដូច្នេះបន្ទាត់កាត់តាម \((\bar{x}, \bar{y})\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22409, 'គេមាន \(n = 5\), \(\sum x_i = 15\), \(\sum y_i = 40\) និង \(a = 2\) ។ គណនា \(b\) ។', NULL, '["\\(2\\)", "\\(10\\)", "\\(8\\)", "\\(5\\)"]', 0, NULL, 1, 'mcq', '\(b = \frac{1}{5}(40 - 2 \times 15) = \frac{10}{5} = 2\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22410, 'ចំពោះចំណុចទិន្នន័យ \((1, 3), (2, 5), (3, 4)\) តើ \(\sum_{i=1}^{3} x_i y_i\) ស្មើប៉ុន្មាន?', NULL, '["\\(12\\)", "\\(25\\)", "\\(22\\)", "\\(18\\)"]', 1, NULL, 1, 'mcq', '\(1(3) + 2(5) + 3(4) = 3 + 10 + 12 = 25\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'easy', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22411, 'គេមាន \(n = 4, \sum x_i = 10, \sum y_i = 16, \sum x_i y_i = 50, \sum x_i^2 = 30\) ។ គណនាមេគុណប្រាប់ទិស \(a\) ។', NULL, '["\\(2\\)", "\\(3\\)", "\\(2.5\\)", "\\(1.5\\)"]', 0, NULL, 2, 'mcq', '\(a = \frac{4(50) - 10(16)}{4(30) - 10^2} = \frac{200 - 160}{120 - 100} = \frac{40}{20} = 2\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22412, 'គេមាន \(n\sum x_i y_i - \sum x_i \sum y_i = 24\), \(n\sum x_i^2 - (\sum x_i)^2 = 36\) និង \(n\sum y_i^2 - (\sum y_i)^2 = 25\) ។ គណនា \(r\) ។', NULL, '["\\(0.6\\)", "\\(0.96\\)", "\\(0.8\\)", "\\(-0.8\\)"]', 2, NULL, 2, 'mcq', '\(r = \frac{24}{\sqrt{36}\times\sqrt{25}} = \frac{24}{6\times 5} = \frac{24}{30} = 0.8\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22413, 'ទិន្នន័យផលិតផល (ពាន់តោន) តាមឆ្នាំគឺ \((2\,020, 12), (2\,021, 15), (2\,022, 19), (2\,023, 22)\) ។ បើតាង \(x = 0\) ជាឆ្នាំ 2020 បន្ទាត់តម្រែតម្រង់គឺ \(y = 3.4x + 11.9\) ។ ប៉ាន់ស្មានផលិតផលឆ្នាំ 2025 ។', NULL, '["\\(22.1\\)", "\\(25.5\\)", "\\(32.3\\)", "\\(28.9\\)"]', 3, NULL, 2, 'mcq', 'ឆ្នាំ 2025 ត្រូវនឹង \(x = 5\) ។ ជំនួសបាន \(y = 3.4(5) + 11.9 = 28.9\) ពាន់តោន ។', 'ការប៉ាន់ស្មានដោយបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22414, 'រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរនៃទិន្នន័យ \((0, 1), (1, 3), (2, 4), (3, 8)\) ។', NULL, '["\\(y = 2.5x + 0.5\\)", "\\(y = 2.2x + 0.7\\)", "\\(y = 1.8x + 1.3\\)", "\\(y = 2x + 1\\)"]', 1, NULL, 2, 'mcq', '\(n=4, \sum x_i=6, \sum y_i=16, \sum x_i y_i=35, \sum x_i^2=14\) បាន \(a = \frac{4(35)-6(16)}{4(14)-36} = \frac{44}{20} = 2.2\) និង \(b = \frac{1}{4}(16 - 2.2 \times 6) = 0.7\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22415, 'គេមាន \(n\sum x_i y_i - \sum x_i \sum y_i = -45\), \(n\sum x_i^2 - (\sum x_i)^2 = 25\) និង \(n\sum y_i^2 - (\sum y_i)^2 = 100\) ។ គណនា \(r\) ។', NULL, '["\\(-0.8\\)", "\\(0.9\\)", "\\(-0.9\\)", "\\(-0.45\\)"]', 2, NULL, 2, 'mcq', '\(r = \frac{-45}{\sqrt{25}\times\sqrt{100}} = \frac{-45}{5\times 10} = -0.9\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22416, 'រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរនៃទិន្នន័យ \((-2, 1), (-1, 2), (0, 4), (1, 6), (2, 7)\) ។', NULL, '["\\(y = 1.5x + 4\\)", "\\(y = 1.2x + 4\\)", "\\(y = 2x + 3\\)", "\\(y = 1.6x + 4\\)"]', 3, NULL, 2, 'mcq', '\(\sum x_i = 0, \sum y_i = 20, \sum x_i y_i = 16, \sum x_i^2 = 10\) បាន \(a = \frac{5(16) - 0}{5(10) - 0} = 1.6\) និង \(b = \frac{20}{5} = 4\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22417, 'បើទិន្នន័យមួយមានមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r = -0.92\) តើគេអាចសន្និដ្ឋានដូចម្តេច?', NULL, '["\\(x\\) និង \\(y\\) មានទំនាក់ទំនងលីនេអ៊ែរគ្នាខ្សោយ ហើយ \\(y\\) ថយតាម \\(x\\)", "\\(x\\) និង \\(y\\) គ្មានទំនាក់ទំនងលីនេអ៊ែរគ្នាទេ", "\\(x\\) និង \\(y\\) មានទំនាក់ទំនងលីនេអ៊ែរគ្នាខ្លាំង ហើយ \\(y\\) ថយតាម \\(x\\)", "\\(x\\) និង \\(y\\) មានទំនាក់ទំនងលីនេអ៊ែរគ្នាខ្លាំង ហើយ \\(y\\) កើនតាម \\(x\\)"]', 2, NULL, 2, 'mcq', 'ដោយ \(|r| = 0.92\) ជិត \(1\) និង \(r < 0\) នាំឱ្យ \(x\) និង \(y\) មានទំនាក់ទំនងលីនេអ៊ែរគ្នាខ្លាំង ហើយ \(y\) ថយតាម \(x\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22418, 'ចំពោះទិន្នន័យ \((0, 2), (1, 3), (2, 7), (3, 8)\) និងបន្ទាត់ \(y = 2x + 2\) តើ \(\sum_{i=1}^{4} d_i^2\) ស្មើប៉ុន្មាន?', NULL, '["\\(2\\)", "\\(0\\)", "\\(4\\)", "\\(6\\)"]', 0, NULL, 2, 'mcq', 'តម្លៃតាមបន្ទាត់គឺ \(2, 4, 6, 8\) ដូច្នេះ \(\sum d_i^2 = (2-2)^2 + (3-4)^2 + (7-6)^2 + (8-8)^2 = 2\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22419, 'បើ \(r = 0.35\) តើការប្រើបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរដើម្បីប៉ាន់ស្មានតម្លៃ \(y\) ទៅតាម \(x\) យ៉ាងណាដែរ?', NULL, '["ពុំទទួលបានលទ្ធផលល្អទេ ព្រោះទំនាក់ទំនងលីនេអ៊ែរខ្សោយ", "តម្លៃ \\(y\\) ថយតាម \\(x\\)", "ចំណុចទាំងអស់ស្ថិតនៅលើបន្ទាត់តែមួយ", "ទទួលបានលទ្ធផលល្អបំផុត ព្រោះ \\(r > 0\\)"]', 0, NULL, 2, 'mcq', '\(r = 0.35\) បង្ហាញថាទំនាក់ទំនងលីនេអ៊ែរខ្សោយ ដូច្នេះការប៉ាន់ស្មានពុំបានលទ្ធផលល្អទេ ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22420, 'ចំពោះចំណុច \((0, 1), (2, 5), (4, 7)\) តើបន្ទាត់ណានៅជិតចំណុចទាំងនេះជាងគេរវាង \(L_1: y = 1.5x + 1.5\) និង \(L_2: y = 2x + 1\)?', NULL, '["\\(L_2\\) ព្រោះ \\(\\sum d_i^2 = 1.5 < 4\\)", "នៅជិតស្មើគ្នា ព្រោះ \\(\\sum d_i^2 = 4\\)", "\\(L_1\\) ព្រោះ \\(\\sum d_i^2 = 2 < 4\\)", "\\(L_1\\) ព្រោះ \\(\\sum d_i^2 = 0.75 < 4\\)"]', 3, NULL, 2, 'mcq', 'ចំពោះ \(L_1\): \(\sum d_i^2 = (-0.5)^2 + 0.5^2 + (-0.5)^2 = 0.75\) និងចំពោះ \(L_2\): \(\sum d_i^2 = 0 + 0 + (-2)^2 = 4\) ដូច្នេះ \(L_1\) នៅជិតជាងគេ ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22421, 'គណនាមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) នៃទិន្នន័យ \((1, 1), (2, 3), (3, 3), (4, 5)\) (បង្គត់ត្រឹម ២ ខ្ទង់ក្រោយក្បៀស) ។', NULL, '["\\(0.90\\)", "\\(0.95\\)", "\\(0.75\\)", "\\(0.85\\)"]', 1, NULL, 2, 'mcq', '\(n=4, \sum x_i=10, \sum y_i=12, \sum x_i y_i=36, \sum x_i^2=30, \sum y_i^2=44\) បាន \(r = \frac{4(36)-10(12)}{\sqrt{4(30)-10^2}\sqrt{4(44)-12^2}} = \frac{24}{\sqrt{20}\sqrt{32}} \approx 0.95\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22422, 'បន្ទាត់តម្រែតម្រង់លីនេអ៊ែរនៃទិន្នន័យ \((1, 3), (3, 8), (5, 10), (k, 15)\) គឺ \(y = 2x + 1\) ។ រកតម្លៃ \(k\) ។', NULL, '["\\(6\\)", "\\(8\\)", "\\(7\\)", "\\(9\\)"]', 2, NULL, 2, 'mcq', 'ដោយ \(\bar{y} = \frac{3+8+10+15}{4} = 9\) ជំនួសក្នុង \(\bar{y} = 2\bar{x} + 1\) បាន \(\bar{x} = 4\) ដូច្នេះ \(k = 16 - 9 = 7\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22423, 'រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរនៃទិន្នន័យ \((1, 4), (2, 6), (3, 7), (4, 10), (5, 13)\) ។', NULL, '["\\(y = 2x + 2\\)", "\\(y = 2.2x + 1.4\\)", "\\(y = 1.8x + 2.6\\)", "\\(y = 2.5x + 1\\)"]', 1, NULL, 2, 'mcq', '\(\sum x_i=15, \sum y_i=40, \sum x_i y_i=142, \sum x_i^2=55\) បាន \(a = \frac{5(142)-15(40)}{5(55)-225} = \frac{110}{50} = 2.2\) និង \(b = \frac{1}{5}(40 - 2.2 \times 15) = 1.4\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22424, 'កាលណាចំណុចទិន្នន័យទាំងអស់ស្ថិតនៅលើបន្ទាត់តែមួយ \(y = mx + c\) តើតម្លៃអប្បបរមានៃ \(\sum d_i^2\) ស្មើប៉ុន្មាន?', NULL, '["\\(1\\)", "\\(n\\)", "\\(-1\\)", "\\(0\\)"]', 3, NULL, 2, 'mcq', 'បើគ្រប់ចំណុចស្ថិតនៅលើបន្ទាត់នោះ គម្លាត \(d_i = 0\) គ្រប់ \(i\) ដូច្នេះ \(\sum d_i^2 = 0\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22425, 'ចំពោះទិន្នន័យ \((-2, 4), (-1, 1), (0, 0), (1, 1), (2, 4)\) តើមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) និងសមីការបន្ទាត់តម្រែតម្រង់គឺជាអ្វី?', NULL, '["\\(r = 1\\) និង \\(y = x^2\\)", "\\(r = 0\\) និង \\(y = 2\\)", "\\(r = -1\\) និង \\(y = -2x + 2\\)", "\\(r = 0\\) និង \\(y = 0\\)"]', 1, NULL, 3, 'mcq', '\(\sum x_i = 0\) និង \(\sum x_i y_i = 0\) ដូច្នេះ \(a = 0, r = 0\) និង \(b = \frac{10}{5} = 2\) ។ ទិន្នន័យនេះមានទំនាក់ទំនងកោង \(y = x^2\) មិនមែនលីនេអ៊ែរទេ ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'hard', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22426, 'គេមានទិន្នន័យ \((1, 2), (2, 5), (3, 7), (4, k)\) ដែលបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរមានមេគុណប្រាប់ទិស \(a = 2\) ។ រកតម្លៃ \(k\) ។', NULL, '["\\(10\\)", "\\(8\\)", "\\(7\\)", "\\(9\\)"]', 1, NULL, 3, 'mcq', '\(n=4, \sum x_i=10, \sum x_i^2=30, \sum y_i=14+k, \sum x_i y_i=33+4k\) ។ តាម \(a = \frac{4(33+4k)-10(14+k)}{20} = \frac{6k-8}{20} = 2\) បាន \(6k = 48 \Rightarrow k = 8\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22427, 'បើគេគុណតម្លៃ \(y_i\) ទាំងអស់នឹង \(10\) តើមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) និងមេគុណប្រាប់ទិស \(a\) ប្រែប្រួលដូចម្តេច?', NULL, '["\\(r\\) កើន \\(10\\) ដង ចំណែក \\(a\\) មិនប្រែប្រួលទេ", "\\(r\\) និង \\(a\\) មិនប្រែប្រួលទេ", "\\(r\\) និង \\(a\\) កើន \\(10\\) ដងទាំងពីរ", "\\(r\\) មិនប្រែប្រួលទេ ចំណែក \\(a\\) កើន \\(10\\) ដង"]', 3, NULL, 3, 'mcq', 'ភាគយកនិងភាគបែងនៃ \(r\) គុណនឹង \(10\) ដូចគ្នា ទើប \(r\) ថេរ រីឯ \(a\) គុណនឹង \(10\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'hard', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22428, 'ចំពោះទិន្នន័យ \((1, 2), (2, 3), (3, 5), (4, 6)\) តើតម្លៃអប្បបរមានៃ \(\sum_{i=1}^{4} [y_i - (ax_i + b)]^2\) ស្មើប៉ុន្មាន?', NULL, '["\\(1.0\\)", "\\(0.4\\)", "\\(0.2\\)", "\\(0.5\\)"]', 2, NULL, 3, 'mcq', 'បន្ទាត់តម្រែតម្រង់គឺ \(y = 1.4x + 0.5\) ។ គណនា \(\sum d_i^2 = 0.1^2 + (-0.3)^2 + 0.3^2 + (-0.1)^2 = 0.2\) ។', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'hard', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22429, 'តើសេចក្តីថ្លែងការណ៍ណាមួយត្រឹមត្រូវជានិច្ចចំពោះទិន្នន័យដែលមាន \(\sum (x_i - \bar{x})^2 > 0\) និង \(\sum (y_i - \bar{y})^2 > 0\)?', NULL, '["\\(a\\) និង \\(r\\) មានសញ្ញាដូចគ្នាជានិច្ច", "បើ \\(r > 0\\) នោះ \\(b > 0\\) ជានិច្ច", "\\(a = r\\) ជានិច្ច", "បើ \\(a > 1\\) នោះ \\(r > 1\\)"]', 0, NULL, 3, 'mcq', 'ភាគយករបស់ \(a\) និង \(r\) គឺ \(n\sum x_i y_i - \sum x_i \sum y_i\) ដូចគ្នា ហើយភាគបែងទាំងពីរវិជ្ជមាន ដូច្នេះ \(a\) និង \(r\) មានសញ្ញាដូចគ្នាជានិច្ច ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'hard', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22430, 'បើទិន្នន័យ \((x_i, y_i)\) មានមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r = 0.85\) ហើយគេប្តូរតួនាទី \(x_i\) និង \(y_i\) ទៅជា \((y_i, x_i)\) តើមេគុណ \(r\) ថ្មីស្មើប៉ុន្មាន?', NULL, '["\\(0.85\\)", "\\(-0.85\\)", "\\(0.85^2\\)", "\\(\\frac{1}{0.85}\\)"]', 0, NULL, 3, 'mcq', 'រូបមន្ត \(r\) មានលក្ខណៈស៊ីមេទ្រីរវាង \(x_i\) និង \(y_i\) ដូច្នេះ \(r\) នៅតែស្មើ \(0.85\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'hard', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22431, 'ទិន្នន័យ \(A: (1,10), (2,20), (3,30), (4,40)\) មាន \(r = 1\) ។ បើប្តូរចំណុចចុងក្រោយជា \((4, 5)\) តើសញ្ញានៃ \(r\) ទៅជាយ៉ាងណា?', NULL, '["វិជ្ជមានជិត \\(0.9\\)", "នៅតែស្មើ \\(1\\)", "អវិជ្ជមាន (\\(r < 0\\))", "ស្មើ \\(0\\) ពិតប្រាកដ"]', 2, NULL, 3, 'mcq', '\(4\sum x_i y_i - \sum x_i \sum y_i = 4(160) - 10(65) = -10 < 0\) ដូច្នេះ \(r < 0\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'hard', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
