INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22432, 'ក្រាបបង្ហាញពីប្រាក់បៀវត្ស \(y\) (ពាន់រៀល) តាមចំនួនឆ្នាំអតីតភាព \(x\) សម្រាប់ \((0, 120), (1, 170), (2, 220), (3, 270)\) ។ បើទំនាក់ទំនងលីនេអ៊ែរនេះបន្ត តើអតីតភាព \(6\) ឆ្នាំទទួលបានប្រាក់បៀវត្សប៉ុន្មាន?', 'g12sc-ac8cac8a72.svg', '["\\(370\\) ពាន់រៀល", "\\(390\\) ពាន់រៀល", "\\(420\\) ពាន់រៀល", "\\(450\\) ពាន់រៀល"]', 2, NULL, 3, 'mcq', 'សមីការបន្ទាត់គឺ \(y = 50x + 120\) ។ ពេល \(x = 6\) បាន \(y = 50(6) + 120 = 420\) ពាន់រៀល ។', 'ទំនាក់ទំនងលីនេអ៊ែរ', 'pisa', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-3ecd9c1d85.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22433, 'ចំនួនភ្ញៀវទេសចរ \(y\) (ម៉ឺននាក់) ពីឆ្នាំ 2018 (\(x=0\)) ដល់ 2022 (\(x=4\)) គឺ \((0, 25.7), (1, 26.3), (2, 29.7), (3, 34.2), (4, 38.3)\) ។ តាមសមីការតម្រែតម្រង់ \(y = 3.31x + 24.22\) ប៉ាន់ស្មានចំនួនភ្ញៀវឆ្នាំ 2023 (\(x=5\)) ។', 'g12sc-3ecd9c1d85.svg', '["\\(42.15\\) ម៉ឺននាក់", "\\(38.30\\) ម៉ឺននាក់", "\\(39.50\\) ម៉ឺននាក់", "\\(40.77\\) ម៉ឺននាក់"]', 3, NULL, 3, 'mcq', 'ជំនួស \(x = 5\) បាន \(y = 3.31(5) + 24.22 = 40.77\) ម៉ឺននាក់ ។', 'ការប៉ាន់ស្មានដោយបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
