INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22434, 'ហាងកាហ្វេមួយកត់ត្រាចំនួនកែវលក់បាន \(y\) (ដប់កែវ) តាមថ្ងៃ \(x\)៖ \((1, 10), (2, 13), (3, 15), (4, 18), (5, 19)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។', 'g12sc-cc83a4a31a.svg', '["\\(y = 2.5x + 7.5\\)", "\\(y = 2x + 9\\)", "\\(y = 2.1x + 8.7\\)", "\\(y = 2.3x + 8.1\\)"]', 3, NULL, 3, 'mcq', '\(n=5, \sum x_i=15, \sum y_i=75, \sum x_i y_i=248, \sum x_i^2=55\) បាន \(a = \frac{5(248)-15(75)}{5(55)-225} = 2.3\) និង \(b = \frac{1}{5}(75 - 2.3 \times 15) = 8.1\) ។', 'ការប៉ាន់ស្មានដោយបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
