INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22435, 'តារាងបង្ហាញម៉ោងរៀន \(x\) និងពិន្ទុ \(y\) របស់សិស្ស ៤ នាក់៖ \((1, 4), (2, 5), (3, 7), (4, 8)\) ។ គណនាមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) ។', 'g12sc-20924b565a.svg', '["\\(0.99\\)", "\\(0.60\\)", "\\(0.75\\)", "\\(0.85\\)"]', 0, NULL, 3, 'mcq', '\(n=4, \sum x_i=10, \sum y_i=24, \sum x_i y_i=67, \sum x_i^2=30, \sum y_i^2=154\) បាន \(r = \frac{4(67)-10(24)}{\sqrt{20}\sqrt{40}} = \frac{28}{20\sqrt{2}} \approx 0.99\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'pisa', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
