INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22436, 'ទិន្នន័យសីតុណ្ហភាព \(x\) (°C) និងថ្លៃកម្តៅ \(y\) (ដុល្លារ) គឺ \((20, 40), (22, 36), (24, 31), (26, 28), (28, 25)\) ។ រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។', 'g12sc-b6699cb892.svg', '["\\(y = -2x + 80\\)", "\\(y = -1.9x + 77.6\\)", "\\(y = 1.9x - 13.6\\)", "\\(y = -1.5x + 68\\)"]', 1, NULL, 3, 'mcq', '\(n=5, \sum x_i=120, \sum y_i=160, \sum x_i y_i=3\,764, \sum x_i^2=2\,920\) បាន \(a = \frac{5(3\,764)-120(160)}{5(2\,920)-120^2} = -1.9\) និង \(b = \frac{1}{5}(160 + 1.9\times 120) = 77.6\) ។', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'pisa', 1, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22437, 'រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរនៃទិន្នន័យ \((1, 3), (2, 5), (3, 9), (4, 11)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 4\) និង \(\sum x_i = 10, \sum y_i = 28\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 3 + 10 + 27 + 44 = 84\) និង \(\sum x_i^2 = 1 + 4 + 9 + 16 = 30\) (1 ពិន្ទុ)
គណនា \(a = \frac{4(84) - 10(28)}{4(30) - 10^2} = \frac{56}{20} = 2.8\) (1 ពិន្ទុ)
គណនា \(b = \frac{1}{4}(28 - 2.8 \times 10) = 0\) (1 ពិន្ទុ)
ដូច្នេះ សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរគឺ \(y = 2.8x\) ។ (1 ពិន្ទុ)', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'easy', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22438, 'គេមានទិន្នន័យ \((0, 5), (1, 8), (2, 10), (3, 13), (4, 14)\) ។ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. ប៉ាន់ស្មានតម្លៃ \(y\) ពេល \(x = 6\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 5, \sum x_i = 10, \sum y_i = 50\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 0 + 8 + 20 + 39 + 56 = 123\) និង \(\sum x_i^2 = 30\) (1 ពិន្ទុ)
គណនា \(a = \frac{5(123) - 10(50)}{5(30) - 10^2} = \frac{115}{50} = 2.3\) (1 ពិន្ទុ)
គណនា \(b = \frac{1}{5}(50 - 2.3 \times 10) = 5.4\) បាន \(y = 2.3x + 5.4\) (1 ពិន្ទុ)
ជំនួស \(x = 6\) បាន \(y = 2.3(6) + 5.4 = 19.2\) ។ (1 ពិន្ទុ)', 'ការប៉ាន់ស្មានដោយបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'medium', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22439, 'ចំពោះទិន្នន័យ \((0, 1), (1, 4), (2, 4), (3, 7)\) គេឱ្យបន្ទាត់ \(L_1: y = 2x + 1\) និង \(L_2: y = 1.8x + 1.3\) ។ គណនា \(\sum d_i^2\) សម្រាប់បន្ទាត់នីមួយៗ រួចបញ្ជាក់ថាបន្ទាត់ណានៅជិតចំណុចទាំងនេះជាងគេ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ចំពោះ \(L_1\): តម្លៃលើបន្ទាត់គឺ \(1, 3, 5, 7\) និងគម្លាត \(d_i = 0, 1, -1, 0\) (1 ពិន្ទុ)
គណនា \(\sum d_i^2(L_1) = 0^2 + 1^2 + (-1)^2 + 0^2 = 2\) (1 ពិន្ទុ)
ចំពោះ \(L_2\): តម្លៃលើបន្ទាត់គឺ \(1.3, 3.1, 4.9, 6.7\) និងគម្លាត \(d_i = -0.3, 0.9, -0.9, 0.3\) (1 ពិន្ទុ)
គណនា \(\sum d_i^2(L_2) = 0.09 + 0.81 + 0.81 + 0.09 = 1.8\) (1 ពិន្ទុ)
ដោយ \(1.8 < 2\) ដូច្នេះបន្ទាត់ \(L_2\) នៅជិតចំណុចទាំងនោះជាងគេ ។ (1 ពិន្ទុ)', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'medium', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22440, 'គណនាមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) នៃទិន្នន័យ \((1, 2), (2, 4), (3, 5), (4, 4), (5, 5)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 5, \sum x_i = 15, \sum y_i = 20\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 66, \sum x_i^2 = 55, \sum y_i^2 = 86\) (1 ពិន្ទុ)
គណនាភាគយក \(5(66) - 15(20) = 330 - 300 = 30\) (1 ពិន្ទុ)
គណនាភាគបែង \(\sqrt{5(55)-15^2}\times\sqrt{5(86)-20^2} = \sqrt{50}\times\sqrt{30} = 10\sqrt{15}\) (1 ពិន្ទុ)
បាន \(r = \frac{30}{10\sqrt{15}} = \frac{\sqrt{15}}{5} \approx 0.77\) ។ (1 ពិន្ទុ)', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'medium', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22441, 'គេមានទិន្នន័យ \((1, 1), (1, 3), (5, 2), (5, 4)\) ។ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. គណនាមេគុណ \(r\) រួចបកស្រាយ ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 4, \sum x_i = 12, \sum y_i = 10, \sum x_i y_i = 34, \sum x_i^2 = 52, \sum y_i^2 = 30\) (1 ពិន្ទុ)
គណនា \(a = \frac{4(34)-12(10)}{4(52)-12^2} = \frac{16}{64} = 0.25\) (1 ពិន្ទុ)
គណនា \(b = \frac{1}{4}(10 - 0.25\times 12) = 1.75\) បាន \(y = 0.25x + 1.75\) (1 ពិន្ទុ)
គណនា \(r = \frac{16}{\sqrt{64}\times\sqrt{20}} = \frac{1}{\sqrt{5}} \approx 0.45\) (1 ពិន្ទុ)
ដោយ \(r \approx 0.45\) ទិន្នន័យមានទំនាក់ទំនងលីនេអ៊ែរខ្សោយ ។ (1 ពិន្ទុ)', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'medium', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22442, 'តាង \(f(b) = \sum_{i=1}^{n} [y_i - (ax_i + b)]^2\) ដែល \(a\) ថេរ ។ ក. រក \(b\) ដែលធ្វើឱ្យ \(f(b)\) តូចបំផុត ។ ខ. បង្ហាញថាបន្ទាត់ \(y = ax + b\) កាត់តាមចំណុចមធ្យម \((\bar{x}, \bar{y})\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្លាត \(f(b) = \sum (y_i - ax_i)^2 - 2b\sum (y_i - ax_i) + nb^2\) (1 ពិន្ទុ)
គណនាដេរីវេ \(f''(b) = -2\sum (y_i - ax_i) + 2nb\) (1 ពិន្ទុ)
ដោះស្រាយ \(f''(b) = 0\) បាន \(b = \frac{1}{n}\left(\sum y_i - a\sum x_i\right)\) (1 ពិន្ទុ)
ដោយ \(f''''(b) = 2n > 0\) នោះ \(b\) នេះធ្វើឱ្យ \(f(b)\) មានតម្លៃអប្បបរមា (1 ពិន្ទុ)
សរសេរ \(b = \bar{y} - a\bar{x} \iff \bar{y} = a\bar{x} + b\) ដូច្នេះបន្ទាត់កាត់តាម \((\bar{x}, \bar{y})\) ។ (1 ពិន្ទុ)', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'hard', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22443, 'ពិនិត្យទិន្នន័យ \((-3,9), (-2,4), (-1,1), (0,0), (1,1), (2,4), (3,9)\) ។ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. គណនា \(r\) រួចបកស្រាយថាតើអាចប្រើបន្ទាត់នេះប៉ាន់ស្មានលទ្ធផលបានឬទេ?', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 7, \sum x_i = 0, \sum y_i = 28\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 0, \sum x_i^2 = 28, \sum y_i^2 = 196\) (1 ពិន្ទុ)
គណនា \(a = 0\) និង \(b = \frac{28}{7} = 4\) បានសមីការ \(y = 4\) (1 ពិន្ទុ)
គណនា \(r = \frac{7(0) - 0}{\sqrt{196}\sqrt{588}} = 0\) (1 ពិន្ទុ)
ដោយ \(r = 0\) គ្មានទំនាក់ទំនងលីនេអ៊ែរទេ (ជាទំនាក់ទំនង \(y = x^2\)) ដូច្នេះពុំអាចប្រើបន្ទាត់នេះប៉ាន់ស្មានបានឡើយ ។ (1 ពិន្ទុ)', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'hard', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22444, 'ចំពោះទិន្នន័យ \((0, 1), (1, 5), (3, 6), (4, 8)\) ៖ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. ប្រៀបធៀប \(\sum d_i^2\) របស់វាជាមួយបន្ទាត់កាត់តាមចំណុចមធ្យមពីរ \(y = \frac{4}{3}x + \frac{7}{3}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា \(n = 4, \sum x_i = 8, \sum y_i = 20, \sum x_i y_i = 55, \sum x_i^2 = 26\) (1 ពិន្ទុ)
គណនា \(a = \frac{4(55)-8(20)}{4(26)-8^2} = \frac{60}{40} = 1.5\) និង \(b = \frac{1}{4}(20 - 1.5\times 8) = 2\) (1 ពិន្ទុ)
សមីការតម្រែតម្រង់គឺ \(y = 1.5x + 2\) និង \(\sum d_i^2 = (-1)^2 + 1.5^2 + (-0.5)^2 + 0^2 = 3.5\) (1 ពិន្ទុ)
ចំពោះ \(y = \frac{4}{3}x + \frac{7}{3}\) បាន \(\sum d_i^2 = (-\frac{4}{3})^2 + (\frac{4}{3})^2 + (-\frac{1}{3})^2 + (\frac{1}{3})^2 = \frac{34}{9} \approx 3.78\) (1 ពិន្ទុ)
ដោយ \(3.5 < 3.78\) បន្ទាត់តម្រែតម្រង់លីនេអ៊ែរមាន \(\sum d_i^2\) តូចជាងបន្ទាត់មធ្យមពីរ ។ (1 ពិន្ទុ)', 'ផលបូកការេប្រវែង និងសមីការតម្រែតម្រង់លីនេអ៊ែរ', 'hard', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22445, 'គេមានទិន្នន័យ \((1, 3), (2, 5), (4, 9), (5, k)\) ។ ក. រកតម្លៃ \(k\) ដើម្បីឱ្យ \(r = 1\) ។ ខ. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរនិង \(\sum d_i^2\) ចំពោះ \(k\) នោះ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដើម្បីឱ្យ \(r = 1\) ចំណុចទាំង ៤ ត្រូវស្ថិតនៅលើបន្ទាត់កើនតែមួយ (1 ពិន្ទុ)
រកបន្ទាត់កាត់តាម \((1, 3)\) និង \((2, 5)\): \(a = \frac{5-3}{2-1} = 2\) (1 ពិន្ទុ)
សមីការបន្ទាត់គឺ \(y - 3 = 2(x - 1) \Rightarrow y = 2x + 1\) (ផ្ទៀងផ្ទាត់ \((4, 9)\)) (1 ពិន្ទុ)
ជំនួស \(x = 5\) បាន \(k = 2(5) + 1 = 11\) (1 ពិន្ទុ)
សមីការបន្ទាត់តម្រែតម្រង់គឺ \(y = 2x + 1\) និង \(\sum d_i^2 = 0\) ។ (1 ពិន្ទុ)', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'hard', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
