INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22446, 'ប្រាក់ចំណាយសាងសង់ \(y\) (ពាន់លានរៀល) ក្នុង ៦ ខែ (មករា \(x=0\) ដល់ មិថុនា \(x=5\)) គឺ \((0, 42), (1, 19), (2, 30), (3, 49), (4, 68), (5, 69)\) ។ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. ប៉ាន់ស្មានប្រាក់ចំណាយក្នុងខែកក្កដា (\(x=6\)) ។', 'g12sc-6701a276a0.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 6, \sum x_i = 15, \sum y_i = 277\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 843\) និង \(\sum x_i^2 = 55\) (1 ពិន្ទុ)
គណនា \(a = \frac{6(843)-15(277)}{6(55)-15^2} = \frac{903}{105} = 8.6\) (1 ពិន្ទុ)
គណនា \(b = \frac{1}{6}(277 - 8.6\times 15) = \frac{74}{3} \approx 24.67\) បាន \(y = 8.6x + \frac{74}{3}\) (1 ពិន្ទុ)
ខែកក្កដា \(x = 6 \Rightarrow y = 8.6(6) + \frac{74}{3} = \frac{1\,144}{15} \approx 76.27\) ពាន់លានរៀល ។ (1 ពិន្ទុ)', 'ការប៉ាន់ស្មានដោយបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-5e69a667a9.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22447, 'តារាងបង្ហាញពិន្ទុតេស្ត \(x\) និងប្រាក់ចំណូលប្រចាំសប្តាហ៍ \(y\) (ពាន់ដុល្លារ) នៃអ្នកលក់ ៥ នាក់៖ \((4, 5), (7, 12), (3, 4), (6, 8), (10, 11)\) ។ គណនាមេគុណតម្រែតម្រង់លីនេអ៊ែរ \(r\) រួចបកស្រាយលទ្ធផល ។', 'g12sc-5e69a667a9.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 5, \sum x_i = 30, \sum y_i = 40\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 274, \sum x_i^2 = 210, \sum y_i^2 = 370\) (1 ពិន្ទុ)
គណនាភាគយក \(5(274) - 30(40) = 170\) (1 ពិន្ទុ)
គណនាភាគបែង \(\sqrt{5(210)-30^2}\times\sqrt{5(370)-40^2} = \sqrt{150\times 250} = 50\sqrt{15}\) (1 ពិន្ទុ)
បាន \(r = \frac{170}{50\sqrt{15}} \approx 0.88\) បញ្ជាក់ថា \(x\) និង \(y\) មានទំនាក់ទំនងលីនេអ៊ែរគ្នាខ្លាំង ។ (1 ពិន្ទុ)', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'pisa', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Analyze');
