INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22448, 'សីតុណ្ហភាពពុះទឹក \(y\) (°C) តាមរយៈកម្ពស់ \(x\) (km) គឺ \((0, 100), (1, 97), (2, 93), (3, 90), (4, 86)\) ។ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. ប៉ាន់ស្មានសីតុណ្ហភាពពុះទឹកនៅកម្ពស់ \(5\text{ km}\) ។', 'g12sc-540f1f95ee.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 5, \sum x_i = 10, \sum y_i = 466\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 0 + 97 + 186 + 270 + 344 = 897\) និង \(\sum x_i^2 = 30\) (1 ពិន្ទុ)
គណនា \(a = \frac{5(897)-10(466)}{5(30)-10^2} = \frac{-175}{50} = -3.5\) (1 ពិន្ទុ)
គណនា \(b = \frac{1}{5}(466 + 3.5\times 10) = 100.2\) បាន \(y = -3.5x + 100.2\) (1 ពិន្ទុ)
នៅកម្ពស់ \(x = 5\text{ km}\) បាន \(y = -3.5(5) + 100.2 = 82.7\text{ °C}\) ។ (1 ពិន្ទុ)', 'មេគុណតម្រែតម្រង់លីនេអ៊ែរ r', 'pisa', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
