INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22449, 'ហាងកង់មួយលក់បាន \(y\) គ្រឿងតាមខែ \(x\)៖ \((0, 14), (1, 18), (2, 21), (3, 25), (4, 27)\) ។ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. ប៉ាន់ស្មានចំនួនលក់នៅពេល \(x = 5\) ។', 'g12sc-9eab74b3ee.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 5, \sum x_i = 10, \sum y_i = 105\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 0 + 18 + 42 + 75 + 108 = 243\) និង \(\sum x_i^2 = 30\) (1 ពិន្ទុ)
គណនា \(a = \frac{5(243)-10(105)}{5(30)-10^2} = \frac{165}{50} = 3.3\) (1 ពិន្ទុ)
គណនា \(b = \frac{1}{5}(105 - 3.3\times 10) = 14.4\) បាន \(y = 3.3x + 14.4\) (1 ពិន្ទុ)
ពេល \(x = 5 \Rightarrow y = 3.3(5) + 14.4 = 30.9\) គ្រឿង (ប្រហែល 31 គ្រឿង) ។ (1 ពិន្ទុ)', 'ការប៉ាន់ស្មានដោយបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'pisa', 0, '12SC', 'សមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ', 'ជំពូកទី 9 : ស្ថិតិពីរអថេរ', NULL, 0, 'Apply');
