INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22450, 'ប្រាក់ចំណាយសាងសង់ \(y\) (ពាន់ដុល្លារ) ក្នុង ៥ ខែ (មករា \(x=0\) ដល់ ឧសភា \(x=4\)) គឺ \((0, 15), (1, 17), (2, 24), (3, 20), (4, 25)\) ។ ក. រកសមីការបន្ទាត់តម្រែតម្រង់លីនេអ៊ែរ ។ ខ. ប៉ាន់ស្មានប្រាក់ចំណាយក្នុងខែមិថុនា (\(x=5\)) ។', 'g12sc-a3fd7d4783.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ \(n = 5, \sum x_i = 10, \sum y_i = 101\) (1 ពិន្ទុ)
គណនា \(\sum x_i y_i = 0 + 17 + 48 + 60 + 100 = 225\) និង \(\sum x_i^2 = 30\) (1 ពិន្ទុ)
គណនា \(a = \frac{5(225)-10(101)}{5(30)-10^2} = \frac{115}{50} = 2.3\) (1 ពិន្ទុ)
គណនា \(b = \frac{1}{5}(101 - 2.3\times 10) = 15.6\) បាន \(y = 2.3x + 15.6\) (1 ពិន្ទុ)
